#!/usr/bin/env python3
"""Build self-contained HTML from frozen accounting keys and qualified references."""
import pathlib,json,html,csv,re,gzip,hashlib,datetime,collections
from acquire import ROOT,body,links
E=lambda x:html.escape(str(x),quote=True)
STATE=ROOT.parent
C=json.loads((STATE/'data/turnout/priority-set.json').read_text())
M={p.stem.replace('.meta',''):json.loads(p.read_text())for p in (ROOT/'source').glob('*.meta.json')}
T={(x['county_fips'],x['source_parent_label']):x for x in json.loads((ROOT/'derived/municipal-reference-matches.json').read_text())}
PDF={x['id']:x for x in json.loads((ROOT/'derived/pdf-pages.json').read_text())}
ADMIN={"Hale's Location","Wentworth's Loc.",'Millsfield',"Pinkham's Grant",'Dixville','Cambridge',"Martin's Location",'Success',"Green's Grant",'Atk. & Gilm. Ac. Gt.',"Bean's Grant","Bean's Purchase","Chandler's Purchase","Crawford's Purchase","Cutt's Grant","Dix's Grant","Erving's Location","Hadley's Purchase",'Kilkenny',"Low & Burbank's Gt.",'Odell',"Sargent's Purchase",'Second College Gt.',"Thompson & Mes's Pur.",'Livermore'}
NOTES={
'Manchester':('manchester-citywidewardmap','Current clerk explicitly states ward lines effective 2021-12-21; PDF says ordained/effective that date. Dated authority supports those ward descriptions, not the synthetic historical key or November reporting crosswalk.'),
'Nashua':('nashua-map','Current clerk links nine-ward PDF, visible effective January 2026/revised February 2026. Underlying extracted text also contains January 2022. Ward 1 legend Broad Street conflicts with current clerk HTML Nashua High North. Historical 2021 proposal is separate and never treated as final.'),
'Concord':('concord-map','Actual ten-ward map linked by current clerk. PDF modification clock 2026-06-04 is metadata, not legal approval. Current linked 44-page street list and polling list retained separately.'),
'Dover':('dover-2012-map','Historical map explicitly labeled 2012 by planning parent. Current November page links six ward sites and MapGeo; exact vendor configuration leads to ward/polling CARTO visualization, but public SQL count failed HTTP500 cannot connect to database. Current full-resolution ward polygons remain unavailable.'),
'Rochester':('rochester-pdf','Actual six-ward PDF downloaded200; direct clerk map parent403 retained. PDF creation/modification clocks are 2020-07-31; no printed effective date found. Historical/current boundary equivalence unverified.'),
'Portsmouth':('portsmouth-map','Actual 2026-labeled five-ward map, complete original55,167,846B retained as ordered gzip parts. Clerk current November3 Ward4 location notice and street list separately retained. Street filename10.06.2026 versus literal footer September1,2026; clocks not interchangeable.'),
'Lebanon':('lebanon-current-linked','Current registering-to-vote page links actual22585 ward PDF. Three ward districts shown. PDF creation clock2026-01-29 is metadata, not effective date. Historical2024 notice linked19860 and search-indexed2022document2081 now404; failures retained, no reconstruction from names.'),
'Claremont':('claremont-map','Actual three-ward PDF linked by city document library, printed May14,2012. Historical ward reference only; current legal boundary and source-key crosswalk unresolved.'),
'Keene':(None,'Current clerk-linked viewer→webmap→WARDS_2022 five full native ward polygons. Layer dataLastEdit2021-10-07; item clock2025 is not effective date. Source2010 Census/VTD fields retained literally; primary city linkage supports municipal ward reference, not automatic approval of Census VTDs or a historical-results join.')}
SPECIAL={
'Derry':('derry-district-map',['derry-district-map','derry-locations'],'Official election page links actual four political/voting district map, D1–D4, and separate ALL ELECTIONS/ALL DISTRICTS1,2,3,4 at Pinkerton Academy. Four districts do not imply four polling sites or new historical rows. No finer Senate return crosswalk.'),
'Merrimack':(None,['merrimack-wards-layer','merrimack-wards-batch-000','merrimack-polling-batch-000'],'Current clerk announces two locations starting April14,2026 and links exact GIS app. Downloaded2 full native ward polygons IDs10/11 plus2 polling points, High/Middle schools. Explicit Joppa/Naticook road assignments remain literal; no allocation of whole-town historical votes to those polygons.'),
'Hudson':(None,['hudson-wards-layer','hudson-wards-batch-000','hudson-locations-batch-000','hudson-ward-one','hudson-ward-two'],'Clerk links two wards by street list and GIS. Downloaded2 full native district polygons plus2 site points. Ward1 street PDF says Hudson Memorial School/1MemorialDrive, while linked GIS says Community Center/12LionsAvenue; unresolved location conflict, no silent preference or geometry correction.'),
'Berlin':('berlin-streets',['berlin-streets'],'Current November clerk identifies precinct1(former wards1/2) and precinct3(former wards3/4); actual12-page street-range PDF retained. Finer precinct polygons unavailable. Frozen historical Berlin remains one unexpanded accounting row, municipal outer boundary is parent reference only.')}

def asset(id):
 m=M[id];return {'id':id,'requested_url':m['requested_url'],'final_url':m.get('final_url'),'http_status':m.get('status'),'retrieved_utc':m.get('completed_utc'),'original_bytes':m.get('original_bytes'),'original_sha256':m.get('original_sha256'),'metadata':'source/'+id+'.meta.json','downloads':m.get('objects',[]),'pages':PDF.get(id,{}).get('pages',[])}

inventory=[]
for u in C['all_units']:
 parent=u['municipal_parent_label'];t=T[(u['county_fips'],parent)];priority=u['rank']<=143;ward=u['ward'];isadmin=parent in ADMIN
 row={'geography_key':u['geography_key'],'priority_rank':u['rank']if priority else None,'source_unit':u,'scope':'no_polygon_unknown_administrative_scope'if isadmin else 'actual_ward_reference'if ward is not None and parent in NOTES else 'ward_reference_gap_parent_only'if ward is not None else 'whole_municipal_reference','municipal_reference':None if isadmin else t,'primary_assets':[],'preview':None,'qualification':'','current_november_2026_approved':False,'current_results_source_id':None,'source_to_geometry_crosswalk':'unverified; no allocation','finer_split_gap':'No approved election-specific polling-site/central-method/result-unit roster or full crosswalk; no November equivalence from labels or counts.'}
 if ward is not None and parent in NOTES:
  aid,note=NOTES[parent];row['qualification']=note
  if parent=='Manchester':aid='manchester-ward'+str(ward)+'map';row['primary_assets']=[asset(aid),asset('manchester-ward'+str(ward)+'description')]
  elif parent=='Keene':row['primary_assets']=[asset('keene-wards-layer'),asset('keene-wards-batch-000')]
  else:row['primary_assets']=[asset(aid)]
  row['preview']=f'previews/keene-ward-{ward}.svg'if parent=='Keene'else PDF[aid]['pages'][0]['preview']
 elif isadmin:
  row['qualification']='Literal administrative/territory accounting identity retained. No polygon assigned; abbreviated/administrative scope not resolved by county, Census code, name similarity or a matching GRANIT label.'
 elif ward is not None:
  row['qualification']='Remainder ward: only clearly labeled municipal parent reference downloaded; actual ward/current geometry remains gap.';row['preview']=t.get('preview')
 else:
  row['primary_assets']=[asset('granit-pbp'),asset('granit-live-layer')];row['preview']=t.get('preview');row['qualification']='Historical whole municipality source row; full GRANIT town/city reference retained from original archive and current service. Corporate boundary only; no current precinct or legal election approval.'
 if parent in SPECIAL:
  aid,ids,note=SPECIAL[parent];row['supplemental_split_assets']=[asset(i)for i in ids];row['qualification']+=' '+note;row['scope']='historical_whole_municipality_with_current_finer_splits'
  if parent in ['Merrimack','Hudson']:row['preview']='previews/'+parent.lower()+'-wards.svg'
  elif parent=='Derry':row['preview']=PDF[aid]['pages'][0]['preview']
 if priority:assert row['preview'] and (ROOT/row['preview']).exists()
 inventory.append(row)
assert len(inventory)==320 and len({x['geography_key']for x in inventory})==320
assert [x['geography_key']for x in inventory[:143]]==C['ordered_priority_keys']
assert len(ADMIN)==25 and sum(x['scope']=='no_polygon_unknown_administrative_scope'for x in inventory)==25
(ROOT/'inventory.json').write_text(json.dumps({'schema_version':'nh-maps-1','contract_sha256':'11c042966c67a50e496ad6f839afd8e3c8b28afe6e2761c6cda1aa51f7ce90fc','historical_source_leaves':320,'priority_count':143,'remainder_count':177,'units':inventory},indent=2)+'\n')
(ROOT/'priority.json').write_text(json.dumps({'ordered_priority_keys':C['ordered_priority_keys'],'units':inventory[:143]},indent=2)+'\n')
css='''body{font:16px/1.5 system-ui,sans-serif;margin:0;color:#172a3b;background:#f1f5f9}header,main{max-width:1280px;margin:auto;padding:24px}header{background:#102e49;color:white;max-width:none}header>div{max-width:1280px;margin:auto}a{color:#08619c}header a{color:#b5e3ff}h1{margin:0}h2{margin:28px 0 12px}input{padding:12px;border:1px solid #8ba7bf;width:min(90%,650px);font:inherit}article{background:white;border:1px solid #ccd9e3;padding:18px;border-radius:10px}article h3{margin:0 0 8px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:16px}.cards img{width:100%;height:230px;object-fit:contain;background:#f8fafc}.badge{display:inline-block;background:#e6eff7;padding:3px 9px;border-radius:5px;font-size:13px}code{overflow-wrap:anywhere;font-size:12px}.note{background:#fff2d5;border-left:4px solid #b47700;padding:16px}.muted{color:#52697c;font-size:14px}table{border-collapse:collapse;width:100%;background:white}td,th{text-align:left;border:1px solid #c9d6e0;padding:9px;vertical-align:top;font-size:13px}th{background:#dce7f1;position:sticky;top:0}.scroll{overflow:auto}summary{cursor:pointer}details{margin:10px 0}nav a{margin-right:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere}img{max-width:100%}[hidden]{display:none!important}'''
def page(title,content):return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'+E(title)+'</title><style>'+css+'</style>'+content+'</html>'
def anchor(path,label):return f'<a href="{E(path)}">{E(label)}</a>'
def downloads(a):
 s=anchor(a['requested_url'],'Primary source')+' · '+anchor(a['metadata'],'HTTP/provenance')
 for i,x in enumerate(a['downloads']):s+=' · '+anchor(x['path'],'Original '+('part '+str(i+1)if len(a['downloads'])>1 else ('gzip'if x['encoding']=='gzip'else 'file')))
 if len(a['downloads'])>1:s+=' · '+anchor('reconstruct.html','Reconstruct exact PDF offline')
 return s
cards=[]
for row in inventory[:143]:
 u=row['source_unit'];assets=row['primary_assets']+row.get('supplemental_split_assets',[]);seenids=set();ds=[]
 for a in assets:
  if a['id']not in seenids:ds.append('<p><b>'+E(a['id'])+'</b><br>'+downloads(a)+'</p>');seenids.add(a['id'])
 t=row['municipal_reference'];extra=''
 if t and t.get('archive_geojson'):extra='<p>Municipal parent reference: '+anchor(t['archive_geojson'],'Archive GeoJSON')+' · '+anchor(t['live_geojson'],'Current-service GeoJSON')+' · '+anchor(t['preview'],'parent preview')+'</p>'
 cards.append(f'<article id="priority-{u["rank"]}" data-key="{E(row["geography_key"])}" data-label="{E(u["native_label"].lower())}"><span class="badge">#{u["rank"]} · {u["reported_candidate_write_in_votes"]:,} reported marks</span><h3>{E(u["native_label"])}</h3><p class="muted">{E(u["county"])} historical source control · {E(row["scope"].replace("_"," "))}</p><a href="{E(row["preview"])}"><img loading="lazy" src="{E(row["preview"])}" alt="{E(u["native_label"])} qualified reference preview"></a><p>{E(row["qualification"])}</p><details><summary>Downloads and exact source scope</summary>{"".join(ds)}{extra}<p class="muted">{E(row["finer_split_gap"])}</p><code>{E(row["geography_key"])}</code><p>Reporting numeric ID: unavailable. November 2026 approval: unverified.</p></details></article>')
rows=[]
for r in inventory:
 u=r['source_unit'];prev=anchor(r['preview'],'preview')if r['preview']else 'No assigned polygon';rows.append(f'<tr data-inventory-key="{E(r["geography_key"])}"><td>{u["rank"]}</td><td>{E(u["native_label"])}</td><td>{E(u["county"])}</td><td>{E(u["municipal_parent_label"])}</td><td>{E(u["ward"] if u["ward"] is not None else "—")}</td><td>{E(r["scope"].replace("_"," "))}</td><td>{prev}</td><td>{E(u["reported_candidate_write_in_votes"])}</td><td><code>{E(r["geography_key"])}</code></td></tr>')
content='<header><div><h1>New Hampshire · town and ward map evidence</h1><p>143 ordered historical priorities · all 320 source accounting leaves · research snapshot October 18, 2026</p><nav>'+anchor('../precinct-maps.md','Research report')+anchor('sources.html','Sources and downloads')+anchor('pages.html','All PDF pages')+anchor('source/SCHEMA.md','Schema')+anchor('validation.json','Offline validation')+'</nav></div></header><main><p class="note"><b>Reference coverage, with exact scope.</b> The 143 keys represent 662,624 / 826,189 reported 2024 candidate plus generic write-in marks (80.20247%). They are 89 whole-municipality rows and 54 wards within 98 distinct explicit municipal parents. A parent outer boundary is not a ward map. Source labels/IDs are not approved November precincts. Current finer Derry/Merrimack/Hudson/Berlin scope stays separate from the historical rows. Blank cells remain unavailable; generic marks are not a valid named-write-in allocation.</p><p>Original geometry and PDF bytes remain intact. SVG/PNG previews are display derivatives. No remote scripts, tiles, fonts or data requests are required; all content below is embedded or local.</p><p>'+anchor('priority.json','Exact priority records')+' · '+anchor('inventory.json','Full 320 inventory')+' · '+anchor('compatibility/diagnostics.json','23 native rosters / 7,360 exact objects')+' · '+anchor('derived/topology.json','Unrepaired geometry diagnostics')+'</p><label for="search">Filter priority previews by literal source label</label><br><input id="search" type="search" placeholder="Town, city, or ward"><p id="shown">143 priority entries</p><div class="cards">'+''.join(cards)+'</div><h2>Full statewide accounting inventory</h2><p>All 177 remainder identities remain below. County and municipal parent controls add no votes. Administrative identities have explicit no-polygon/unknown scope. Reporting IDs remain unavailable.</p><div class="scroll"><table><thead><tr><th>Rank</th><th>Literal source label</th><th>Source county control</th><th>Explicit parent</th><th>Ward</th><th>Asset scope</th><th>Reference</th><th>Reported marks</th><th>Historical key</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></main><script>const box=document.getElementById("search");box.addEventListener("input",()=>{let n=0;for(const a of document.querySelectorAll("article[data-key]")){a.hidden=!a.dataset.label.includes(box.value.trim().toLowerCase());if(!a.hidden)n++;}document.getElementById("shown").textContent=n+" of 143 priority entries";});</script>'
(ROOT/'index.html').write_text(page('New Hampshire map evidence',content))
# All original source requests, successful and blocked, are inspectable offline.
sources=[];recipes=[]
for id,m in sorted(M.items()):
 a=asset(id);parent=m.get('parent');recipes.append({'id':id,'url':m['requested_url'],'parent':parent,'note':m.get('note',''),'kind':m.get('format')})
 sources.append('<tr><td id="'+E(id)+'">'+E(id)+'</td><td>'+E(m.get('status'))+'</td><td>'+E(parent or 'Direct primary URL / search discovery; no observed parent edge claimed')+'</td><td>'+downloads(a)+'</td><td>'+E(m.get('original_bytes'))+'<br><code>'+E(m.get('original_sha256'))+'</code></td><td>'+E(m.get('note',''))+'</td></tr>')
(ROOT/'source/acquisition-plan.json').write_text(json.dumps(sorted(recipes,key=lambda x:M[x['id']]['requested_utc']),indent=2)+'\n')
(ROOT/'sources.html').write_text(page('Primary map sources','<main><h1>Original downloads and authority chains</h1><p>'+anchor('index.html','Map index')+' · '+anchor('source/acquisition-plan.json','Reproducible acquisition plan')+'</p><p>HTTP200 alone does not approve geography. Metadata retains exact requested/final URLs, redirect headers, response status, retrieval UTC, stored/original hashes and ordered reconstruction. Generic/challenge/404/database-error bodies remain evidence of failures, not completed maps. The historical proposal and legacy map PDFs stay separate from current publication.</p><table><tr><th>Capture</th><th>HTTP</th><th>Parent capture</th><th>Source / local original</th><th>Original bytes/hash</th><th>Qualification</th></tr>'+''.join(sources)+'</table></main>'))
pages=[]
for id,p in PDF.items():
 pages.append('<section><h2>'+E(id)+' · '+str(p['page_count'])+' pages</h2><p>'+downloads(asset(id))+'</p><div class="cards">'+''.join('<article><p>Page '+str(x['page'])+'</p><a href="'+E(x['preview'])+'"><img loading="lazy" src="'+E(x['preview'])+'" alt="'+E(id)+' page '+str(x['page'])+'"></a></article>'for x in p['pages'])+'</div></section>')
(ROOT/'pages.html').write_text(page('PDF page evidence','<main><h1>Actual original PDF page previews</h1><p>'+anchor('index.html','Map index')+' · '+anchor('derived/pdf-pages.json','Page dimensions, counts and metadata')+' · '+anchor('derived/visual-review.json','Visual review and content qualifications')+'</p><p>Every retained successful PDF page rendered, without cropping the original. Previews are reduced resolution; use the original for street text. The capture ID portsmouth-officials holds the actual linked ten-page general sample ballots; its exact URL and visual content govern. The correctly selected elected officials table is portsmouth-elected-officials.</p>'+''.join(pages)+'</main>'))
# Browser reconstruction reads local selected files, never file:// fetches.
pm=M['portsmouth-map'];parts=[x['path'].split('/')[-1]for x in pm['objects']]
helper='<main><h1>Reconstruct the original Portsmouth PDF offline</h1><p>'+anchor('index.html','Map index')+'</p><p>Select both saved gzip parts in the file picker. The browser decompresses them in documented order, checks the complete SHA-256 and byte count, then offers the original PDF. No upload or network request occurs.</p><ol>'+''.join('<li>'+anchor(x['path'],x['path'])+'</li>'for x in pm['objects'])+'</ol><input id="parts" type="file" multiple accept=".gz"><button id="rebuild">Verify and reconstruct</button><p id="status"></p><a id="download" hidden>Download exact original PDF</a><p>Command line: <code>python3 maps/reconstruct.py portsmouth-map --output /tmp/portsmouth-map.pdf</code> from the New Hampshire state directory. Keep large reconstructions outside maps/.</p></main><script>const expectedNames='+json.dumps(parts)+';document.getElementById("rebuild").onclick=async()=>{const status=document.getElementById("status");try{const selected=Array.from(document.getElementById("parts").files);const arrays=[];for(const name of expectedNames){const file=selected.find(f=>f.name===name);if(!file)throw Error("Missing "+name);const stream=file.stream().pipeThrough(new DecompressionStream("gzip"));arrays.push(new Uint8Array(await new Response(stream).arrayBuffer()));}const all=new Uint8Array(arrays.reduce((n,a)=>n+a.length,0));let p=0;for(const a of arrays){all.set(a,p);p+=a.length;}const digest=Array.from(new Uint8Array(await crypto.subtle.digest("SHA-256",all))).map(x=>x.toString(16).padStart(2,"0")).join("");if(all.length!=='+str(pm['original_bytes'])+'||digest!=='+json.dumps(pm['original_sha256'])+')throw Error("Original hash/size mismatch");const link=document.getElementById("download");link.href=URL.createObjectURL(new Blob([all],{type:"application/pdf"}));link.download="portsmouth-original.pdf";link.hidden=false;status.textContent="Verified "+all.length+" bytes; SHA-256 "+digest;}catch(e){status.textContent=e.message;}};</script>'
(ROOT/'reconstruct.html').write_text(page('Offline original PDF reconstruction',helper))
with (ROOT/'manifest.csv').open('w')as f:
 fields=['rank','geography_key','native_label','county_fips','ward','scope','preview','current_november_2026_approved'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for r in inventory[:143]:w.writerow({'rank':r['priority_rank'],'geography_key':r['geography_key'],'native_label':r['source_unit']['native_label'],'county_fips':r['source_unit']['county_fips'],'ward':r['source_unit']['ward'],'scope':r['scope'],'preview':r['preview'],'current_november_2026_approved':False})
print('Built143ordered cards;320inventory;25administrative no-polygon;98priorityparents;44PDFcapture gallery')
